// Resolves a user's preferences: workspace defaults overlaid with the user's own overrides.
export type Preferences = Readonly<Record<string, string>>;

export interface PreferenceSource {
  fetchDefaults(workspace: string): Promise<Preferences>;
  fetchOverrides(workspace: string, user: string): Promise<Preferences>;
}

export async function resolvePreferences(source: PreferenceSource, workspace: string, user: string): Promise<Preferences> {
  const defaults = await source.fetchDefaults(workspace);
  const overrides = await source.fetchOverrides(workspace, user);
  return { ...defaults, ...overrides };
}

