// Hidden suite for T02, written from the spec before the implementation.
import { describe, expect, it } from "vitest";
import { createPreferenceCache, resolvePreferences } from "../src/preferences.ts";
import type { PreferenceSource, Preferences } from "../src/preferences.ts";

function coded(code: string): Error {
  return Object.assign(new Error(code), { code });
}

interface FakeSource extends PreferenceSource {
  readonly calls: { defaults: number; overrides: number };
}

/** Defaults always come from `defaults` unless `defaultFailures` still holds an error to throw first. */
function fakeSource(
  defaults: Preferences,
  overrides: Readonly<Record<string, Preferences>>,
  defaultFailures: unknown[] = [],
): FakeSource {
  const calls = { defaults: 0, overrides: 0 };
  return {
    calls,
    async fetchDefaults(): Promise<Preferences> {
      calls.defaults += 1;
      const failure = defaultFailures.shift();
      if (failure !== undefined) throw failure;
      return defaults;
    },
    async fetchOverrides(_workspace: string, user: string): Promise<Preferences> {
      calls.overrides += 1;
      const found = overrides[user];
      if (found === undefined) throw coded("not_found");
      return found;
    },
  };
}

const DEFAULTS: Preferences = { theme: "light", lang: "en" };
const OVERRIDES: Readonly<Record<string, Preferences>> = { ann: { theme: "dark" } };

describe("resolvePreferences", () => {
  it("overlays the user's overrides on the workspace defaults", async () => {
    const source = fakeSource(DEFAULTS, OVERRIDES);
    expect(await resolvePreferences(source, "w1", "ann")).toEqual({ theme: "dark", lang: "en" });
  });

  it("returns the defaults for a user without overrides", async () => {
    const source = fakeSource(DEFAULTS, OVERRIDES);
    expect(await resolvePreferences(source, "w1", "bo")).toEqual({ theme: "light", lang: "en" });
  });

  it("passes other override failures to the caller", async () => {
    const boom = coded("timeout");
    const source: PreferenceSource = {
      fetchDefaults: async () => DEFAULTS,
      fetchOverrides: async () => {
        throw boom;
      },
    };
    await expect(resolvePreferences(source, "w1", "ann")).rejects.toBe(boom);
  });

  it("passes default failures to the caller", async () => {
    const boom = coded("unavailable");
    const source = fakeSource(DEFAULTS, OVERRIDES, [boom]);
    await expect(resolvePreferences(source, "w1", "ann")).rejects.toBe(boom);
  });
});

describe("createPreferenceCache", () => {
  it("serves a cached result until the ttl has elapsed", async () => {
    let clock = 1000;
    const source = fakeSource(DEFAULTS, OVERRIDES);
    const cache = createPreferenceCache(source, { ttlMs: 500, now: () => clock });
    await cache.get("w1", "ann");
    clock = 1499;
    expect(await cache.get("w1", "ann")).toEqual({ theme: "dark", lang: "en" });
    expect(source.calls.defaults).toBe(1);
  });

  it("starts a new load exactly when the ttl has elapsed", async () => {
    let clock = 1000;
    const source = fakeSource(DEFAULTS, OVERRIDES);
    const cache = createPreferenceCache(source, { ttlMs: 500, now: () => clock });
    await cache.get("w1", "ann");
    clock = 1500;
    await cache.get("w1", "ann");
    expect(source.calls.defaults).toBe(2);
  });

  it("shares one load between concurrent calls", async () => {
    const source = fakeSource(DEFAULTS, OVERRIDES);
    const cache = createPreferenceCache(source, { ttlMs: 500, now: () => 0 });
    const [first, second] = await Promise.all([cache.get("w1", "ann"), cache.get("w1", "ann")]);
    expect(first).toEqual(second);
    expect(source.calls.defaults).toBe(1);
    expect(source.calls.overrides).toBe(1);
  });

  it("keeps each user's preferences apart", async () => {
    const source = fakeSource(DEFAULTS, OVERRIDES);
    const cache = createPreferenceCache(source, { ttlMs: 500, now: () => 0 });
    expect(await cache.get("w1", "ann")).toEqual({ theme: "dark", lang: "en" });
    expect(await cache.get("w1", "bo")).toEqual({ theme: "light", lang: "en" });
  });

  it("keeps each workspace's preferences apart", async () => {
    const source = fakeSource(DEFAULTS, OVERRIDES);
    const cache = createPreferenceCache(source, { ttlMs: 500, now: () => 0 });
    await cache.get("w1", "ann");
    await cache.get("w2", "ann");
    expect(source.calls.defaults).toBe(2);
  });

  it("returns the same rejection to callers that shared a failed load", async () => {
    const boom = coded("unavailable");
    const source = fakeSource(DEFAULTS, OVERRIDES, [boom]);
    const cache = createPreferenceCache(source, { ttlMs: 500, now: () => 0 });
    const first = cache.get("w1", "ann");
    const second = cache.get("w1", "ann");
    await expect(first).rejects.toBe(boom);
    await expect(second).rejects.toBe(boom);
    expect(source.calls.defaults).toBe(1);
  });

  it("starts a new load after a failed one", async () => {
    const boom = coded("unavailable");
    const source = fakeSource(DEFAULTS, OVERRIDES, [boom]);
    const cache = createPreferenceCache(source, { ttlMs: 500, now: () => 0 });
    await expect(cache.get("w1", "ann")).rejects.toBe(boom);
    expect(await cache.get("w1", "ann")).toEqual({ theme: "dark", lang: "en" });
    expect(source.calls.defaults).toBe(2);
  });
});
